function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }

function page(title, body) {
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
        '<title>' + esc(title) + '</title>' +
        '<style>body{font-family:sans-serif;max-width:820px;margin:30px auto;padding:0 16px;color:#22303F}' +
        'table{border-collapse:collapse;width:100%;margin:16px 0}th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:14px}' +
        'th{background:#0E7C86;color:#fff}.ok{color:#1a7f37;font-weight:700}.bad{color:#b42318;font-weight:700}' +
        'form.inline{display:inline}button{cursor:pointer;border:none;border-radius:4px;padding:5px 10px;font-size:12px;margin:0 2px}' +
        '.revoke{background:#b42318;color:#fff}.reactivate{background:#1a7f37;color:#fff}.rotate{background:#946200;color:#fff}' +
        'fieldset{margin-top:24px;border:1px solid #ccc;border-radius:6px}label{display:block;margin:10px 0}input{padding:6px;margin:4px 0;width:100%;box-sizing:border-box}' +
        '.create{background:#0E7C86;color:#fff;padding:8px 16px;font-size:14px}</style></head>' +
        '<body><h2>🌱 Riego Hub — administración de áreas</h2>' + body + '</body></html>';
}

global.get('pgPool').query('SELECT id, name, status, last_heartbeat_at, internal_url FROM riego_hub.areas ORDER BY created_at')
    .then(function(result) {
        var rows = result.rows.map(function(a) {
            var estado = a.status === 'revoked' ? '<span class="bad">revocada</span>' : '<span class="ok">activa</span>';
            var hb = a.last_heartbeat_at ? new Date(a.last_heartbeat_at).toLocaleString('es-AR') : 'nunca';
            var toggle = a.status === 'revoked'
                ? '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/reactivate"><button class="reactivate">Reactivar</button></form>'
                : '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/revoke"><button class="revoke">Revocar</button></form>';
            var rotate = '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/rotate-key" onsubmit="return confirm(\'Esto invalida la key actual del area. Confirmar?\');"><button class="rotate">Rotar key</button></form>';
            var estructura = '<a href="/hub/areas/' + esc(a.id) + '/estructura">Estructura</a>';
            var internalUrlForm = '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/internal-url">' + '<input name="internal_url" value="' + esc(a.internal_url || '') + '" placeholder="http://nodered:1880" style="width:170px;font-size:12px;padding:3px;"> ' + '<button style="padding:4px 8px;font-size:11px;">Guardar</button></form>';
        return '<tr><td>' + esc(a.id) + '</td><td>' + esc(a.name) + '</td><td>' + estado + '</td><td>' + esc(hb) + '</td><td>' + toggle + ' ' + rotate + ' ' + estructura + '</td><td>' + internalUrlForm + '</td></tr>';
        }).join('');
        if (!rows) rows = '<tr><td colspan="5">Todavia no hay areas creadas.</td></tr>';
        var body = '<table><tr><th>ID</th><th>Nombre</th><th>Estado</th><th>Ultimo heartbeat</th><th>Acciones</th><th>URL interna (gateway)</th></tr>' + rows + '</table>' +
            '<fieldset><legend>Crear area nueva</legend>' +
            '<form method="POST" action="/hub/areas">' +
            '<label>Nombre<input name="name" required placeholder="Ej: Finca Norte"></label>' +
            '<label>ID (opcional, se genera del nombre si se deja vacio)<input name="id" placeholder="Ej: finca-norte"></label>' +
            '<label>Key existente (opcional -- para dar de alta un area que ya tiene una key funcionando, sin rotarla)<input name="existing_key" placeholder="Dejar vacio para generar una key nueva"></label>' +
            '<p><button class="create" type="submit">Crear area</button></p>' +
            '</form></fieldset>';
        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = page('Riego Hub', body);
        node.send(msg);
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = page('Error', '<p>Error consultando areas: ' + esc(err.message) + '</p>');
        node.send(msg);
    });
return null;

function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }

function renderKeyOncePage(id, name, key, imported) {
    return '<!doctype html><html><head><meta charset="utf-8"><title>Area ' + (imported ? 'importada' : 'creada') + '</title>' +
        '<style>body{font-family:sans-serif;max-width:600px;margin:40px auto;padding:0 16px;color:#22303F}' +
        'code{display:block;background:#f4f4f4;padding:12px;border-radius:6px;word-break:break-all;font-size:14px}</style></head>' +
        '<body><h2>✅ Área "' + esc(name) + '" (' + esc(id) + ') ' + (imported ? 'importada' : 'creada') + '</h2>' +
        '<p><strong>' + (imported ? 'Key confirmada' : 'Nueva key') + ' (copiala ahora, no se vuelve a mostrar):</strong></p>' +
        '<code>' + esc(key) + '</code>' +
        '<p>Poné este valor como <code>RIEGO_AREA_KEY</code> en el <code>.env</code> del Edge de esta área' +
        (imported ? ' (si ya lo tenía configurado así, no hace falta tocar nada).' : ', junto con <code>RIEGO_AREA_ID=' + esc(id) + '</code> y <code>HUB_URL</code> apuntando a este Hub.') +
        '</p><p><a href="/hub/areas">Volver a la lista</a></p></body></html>';
}

var body = msg.payload || {};
var name = (body.name || '').trim();
if (!name) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>Falta el nombre del area. <a href="/hub/areas">Volver</a></p>';
    return msg;
}
var areaId = (body.id || '').trim().toLowerCase();
if (!areaId) {
    areaId = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
if (!/^[a-z0-9-]+$/.test(areaId)) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>ID invalido (solo minusculas, numeros y guiones). <a href="/hub/areas">Volver</a></p>';
    return msg;
}

var existingKey = (body.existing_key || '').trim();
var key = existingKey || crypto.randomBytes(32).toString('hex');
var keyHash = crypto.createHash('sha256').update(key).digest('hex');

global.get('pgPool').query(
    'INSERT INTO riego_hub.areas (id, name, key_hash) VALUES ($1, $2, $3)',
    [areaId, name, keyHash]
).then(function() {
    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = renderKeyOncePage(areaId, name, key, !!existingKey);
    node.send(msg);
}).catch(function(err) {
    msg.statusCode = err.code === '23505' ? 409 : 500;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>Error creando el area: ' + esc(err.message) + '</p><p><a href="/hub/areas">Volver</a></p>';
    node.send(msg);
});
return null;

var areaId = msg.req.params.id;
global.get('pgPool').query("UPDATE riego_hub.areas SET status='revoked' WHERE id=$1", [areaId])
    .then(function() { msg.statusCode = 302; msg.headers = { Location: '/hub/areas' }; node.send(msg); })
    .catch(function(err) { msg.statusCode = 500; msg.headers = { 'Content-Type': 'text/plain' }; msg.payload = 'Error: ' + err.message; node.send(msg); });
return null;

var areaId = msg.req.params.id;
global.get('pgPool').query("UPDATE riego_hub.areas SET status='active' WHERE id=$1", [areaId])
    .then(function() { msg.statusCode = 302; msg.headers = { Location: '/hub/areas' }; node.send(msg); })
    .catch(function(err) { msg.statusCode = 500; msg.headers = { 'Content-Type': 'text/plain' }; msg.payload = 'Error: ' + err.message; node.send(msg); });
return null;

function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }

function renderKeyOncePage(id, name, key, imported) {
    return '<!doctype html><html><head><meta charset="utf-8"><title>Area ' + (imported ? 'importada' : 'creada') + '</title>' +
        '<style>body{font-family:sans-serif;max-width:600px;margin:40px auto;padding:0 16px;color:#22303F}' +
        'code{display:block;background:#f4f4f4;padding:12px;border-radius:6px;word-break:break-all;font-size:14px}</style></head>' +
        '<body><h2>✅ Área "' + esc(name) + '" (' + esc(id) + ') ' + (imported ? 'importada' : 'creada') + '</h2>' +
        '<p><strong>' + (imported ? 'Key confirmada' : 'Nueva key') + ' (copiala ahora, no se vuelve a mostrar):</strong></p>' +
        '<code>' + esc(key) + '</code>' +
        '<p>Poné este valor como <code>RIEGO_AREA_KEY</code> en el <code>.env</code> del Edge de esta área' +
        (imported ? ' (si ya lo tenía configurado así, no hace falta tocar nada).' : ', junto con <code>RIEGO_AREA_ID=' + esc(id) + '</code> y <code>HUB_URL</code> apuntando a este Hub.') +
        '</p><p><a href="/hub/areas">Volver a la lista</a></p></body></html>';
}

var areaId = msg.req.params.id;
var key = crypto.randomBytes(32).toString('hex');
var keyHash = crypto.createHash('sha256').update(key).digest('hex');
global.get('pgPool').query('UPDATE riego_hub.areas SET key_hash=$1 WHERE id=$2 RETURNING name', [keyHash, areaId])
    .then(function(result) {
        if (!result.rows[0]) {
            msg.statusCode = 404;
            msg.headers = { 'Content-Type': 'text/plain' };
            msg.payload = 'Area no encontrada';
            return node.send(msg);
        }
        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = renderKeyOncePage(areaId, result.rows[0].name, key, false);
        node.send(msg);
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'text/plain' };
        msg.payload = 'Error: ' + err.message;
        node.send(msg);
    });
return null;

var body = msg.payload || {};
var areaId = (body.area_id || '').trim();
var areaKey = (body.area_key || '').trim();
if (!areaId || !areaKey) {
    msg.statusCode = 400;
    msg.payload = { ok: false, reason: 'missing_fields' };
    return msg;
}
var keyHash = crypto.createHash('sha256').update(areaKey).digest('hex');
global.get('pgPool').query('SELECT name, key_hash, status, structure_version, structure FROM riego_hub.areas WHERE id=$1', [areaId])
    .then(function(result) {
        var area = result.rows[0];
        if (!area || area.key_hash !== keyHash) {
            msg.statusCode = 401;
            msg.payload = { ok: false, reason: 'invalid_key' };
            return node.send(msg);
        }
        if (area.status === 'revoked') {
            msg.statusCode = 403;
            msg.payload = { ok: false, reason: 'revoked' };
            return node.send(msg);
        }
        var ip = (msg.req.headers['x-forwarded-for'] || (msg.req.connection && msg.req.connection.remoteAddress) || '').toString();

        // Edge credentials may report liveness, never provision central structure.
        var seedPromise = Promise.resolve();

        seedPromise.then(function() {
            return global.get('pgPool').query(
                'UPDATE riego_hub.areas SET last_heartbeat_at = now(), last_heartbeat_ip = $2 WHERE id = $1 RETURNING structure_version, structure',
                [areaId, ip]
            );
        }).then(function(updateResult) {
            var row = updateResult.rows[0];
            var clientVersion = Number(body.structure_version) || 0;
            var payload = { ok: true, area_name: area.name, server_time: new Date().toISOString(), structure_version: row.structure_version };
            if (clientVersion !== row.structure_version) {
                payload.structure = row.structure;
            }
            msg.statusCode = 200;
            msg.payload = payload;
            node.send(msg);
        }).catch(function(err) {
            msg.statusCode = 500;
            msg.payload = { ok: false, reason: 'internal_error' };
            node.send(msg);
        });
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.payload = { ok: false, reason: 'internal_error' };
        node.send(msg);
    });
return null;

msg.statusCode = 302;
msg.headers = { Location: '/hub/areas' };
return msg;

function loadStructure(areaId) {
    return global.get('pgPool').query('SELECT structure, structure_version FROM riego_hub.areas WHERE id = $1', [areaId])
        .then(function(result) {
            if (!result.rows[0]) return null;
            var s = result.rows[0].structure || {};
            return {
                zonas: Array.isArray(s.zonas) ? s.zonas : [],
                valvulas: Array.isArray(s.valvulas) ? s.valvulas : [],
                sensores: Array.isArray(s.sensores) ? s.sensores : [],
                config: Object.assign({ watchdogMinutos: 60 }, s.config || {}),
                version: result.rows[0].structure_version
            };
        });
}
function saveStructure(areaId, structure) {
    var toSave = { zonas: structure.zonas, valvulas: structure.valvulas, sensores: structure.sensores, config: structure.config };
    return global.get('pgPool').query(
        'UPDATE riego_hub.areas SET structure = $2, structure_version = structure_version + 1 WHERE id = $1',
        [areaId, JSON.stringify(toSave)]
    );
}
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }
global.set('hubLoadStructure', loadStructure);
global.set('hubSaveStructure', saveStructure);
global.set('hubEsc', esc);
return null;

var esc = global.get('hubEsc');

function page(areaId, areaNombre, body) {
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
        '<title>Estructura - ' + esc(areaNombre) + '</title>' +
        '<style>body{font-family:sans-serif;max-width:900px;margin:30px auto;padding:0 16px;color:#22303F}' +
        'table{border-collapse:collapse;width:100%;margin:10px 0}th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;font-size:13px;vertical-align:top}' +
        'th{background:#0E7C86;color:#fff}h3{margin-top:36px}' +
        'form.inline{display:inline}button{cursor:pointer;border:none;border-radius:4px;padding:5px 10px;font-size:12px;margin:0 2px}' +
        '.del{background:#b42318;color:#fff}.save{background:#1a7f37;color:#fff}.create{background:#0E7C86;color:#fff;padding:8px 16px;font-size:14px}' +
        'fieldset{margin-top:16px;border:1px solid #ccc;border-radius:6px}label{display:block;margin:8px 0;font-size:12px}' +
        'input,select{padding:5px;width:100%;box-sizing:border-box;font-size:13px}' +
        '.editform input, .editform select{width:80px; display:inline-block; margin:0 4px 0 0}</style></head>' +
        '<body><p><a href="/hub/areas">&larr; Areas</a></p>' +
        '<h2>🔧 Estructura de ' + esc(areaNombre) + '</h2>' + body + '</body></html>';
}

var areaId = msg.req.params.id;
global.get('pgPool').query('SELECT name FROM riego_hub.areas WHERE id = $1', [areaId]).then(function(areaResult) {
    if (!areaResult.rows[0]) { msg.statusCode = 404; msg.payload = 'Area no encontrada'; return node.send(msg); }
    var areaNombre = areaResult.rows[0].name;
    global.get('hubLoadStructure')(areaId).then(function(s) {
        var zonasRows = s.zonas.map(function(z) {
            var valvulasDeZona = s.valvulas.filter(function(v) { return v.zonaId === z.id; });
            var valvulasHtml = valvulasDeZona.map(function(v) {
                var detalleCanal = v.tipo === 'cortina' ? ('subir: ' + v.canalSubir + ', bajar: ' + v.canalBajar) : ('canal ' + v.canal);
            return '<tr><td colspan="2" style="padding-left:20px;">&#8627; ' + esc(v.nombre) + ' (' + detalleCanal + ')' + (v.autoApagadoSeg ? ' &middot; auto-apagado ' + v.autoApagadoSeg + 's' : '') + '</td>' +
                    '<td>' +
                    '<form class="inline editform" method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas/' + v.id + '/editar">' +
                    '<input name="nombre" value="' + esc(v.nombre) + '" placeholder="Nombre">' +
                    (v.tipo === 'cortina'
                        ? '<input type="number" name="canalSubir" value="' + v.canalSubir + '" placeholder="Canal subir">' + '<input type="number" name="canalBajar" value="' + v.canalBajar + '" placeholder="Canal bajar">'
                        : '<input type="number" name="canal" value="' + v.canal + '" placeholder="Canal">') +
                    '<input type="number" name="autoApagadoSeg" value="' + (v.autoApagadoSeg || '') + '" placeholder="Auto-apagado seg">' +
                    '<button class="save" type="submit">Guardar</button></form> ' +
                    '<form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas/' + v.id + '/eliminar" onsubmit="return confirm(\'Eliminar actuador ' + esc(v.nombre).replace(/'/g, "\\'") + '?\');">' +
                    '<button class="del" type="submit">Eliminar</button></form>' +
                    '</td></tr>';
            }).join('');
            return '<tr><td>' + esc(z.nombre) + '</td><td>Unit ' + z.unitid + ' &middot; ' + z.canalesTarjeta + ' canales &middot; max ' + z.maxSimultaneas + ' a la vez</td>' +
                '<td>' +
                '<form class="inline editform" method="POST" action="/hub/areas/' + esc(areaId) + '/zonas/' + z.id + '/editar">' +
                '<input name="nombre" value="' + esc(z.nombre) + '" placeholder="Nombre">' +
                '<input type="number" name="unitid" value="' + z.unitid + '" placeholder="Unit ID">' +
                '<input type="number" name="canalesTarjeta" value="' + z.canalesTarjeta + '" placeholder="Canales">' +
                '<input type="number" name="maxSimultaneas" value="' + z.maxSimultaneas + '" placeholder="Max">' +
                '<button class="save" type="submit">Guardar</button></form> ' +
                '<form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/zonas/' + z.id + '/eliminar" onsubmit="return confirm(\'Eliminar zona ' + esc(z.nombre).replace(/'/g, "\\'") + ' y sus actuadores?\');">' +
                '<button class="del" type="submit">Eliminar</button></form>' +
                '</td></tr>' + valvulasHtml;
        }).join('');
        if (!zonasRows) zonasRows = '<tr><td colspan="3">Todavia no hay zonas.</td></tr>';

        var opcionesZonas = s.zonas.map(function(z) { return '<option value="' + z.id + '">' + esc(z.nombre) + ' (Unit ' + z.unitid + ')</option>'; }).join('');

        var sensoresRows = s.sensores.map(function(sn) {
            var origen = sn.fuente === 'mqtt' ? ('MQTT ' + esc(sn.mqttDevEui) + ' / ' + esc(sn.mqttPath)) : ('HA ' + esc(sn.haEntityId));
            return '<tr><td>' + esc(sn.nombre) + '</td><td>' + esc(sn.tipo) + ' (' + esc(sn.unidad) + ')</td><td>' + origen + '</td>' +
                '<td><form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/sensores/' + sn.id + '/eliminar" onsubmit="return confirm(\'Eliminar sensor ' + esc(sn.nombre).replace(/'/g, "\\'") + '?\');">' +
                '<button class="del" type="submit">Eliminar</button></form></td></tr>';
        }).join('');
        if (!sensoresRows) sensoresRows = '<tr><td colspan="4">Todavia no hay sensores.</td></tr>';

        var body =
            '<h3>Zonas (tarjetas Modbus)</h3>' +
            '<table><tr><th>Nombre</th><th>Detalle</th><th>Acciones</th></tr>' + zonasRows + '</table>' +
            '<fieldset><legend>Crear zona</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/zonas">' +
            '<label>Nombre<input name="nombre" required></label>' +
            '<label>Unit ID (Modbus)<input type="number" name="unitid" required></label>' +
            '<label>Canales de la tarjeta<input type="number" name="canalesTarjeta" value="8" required></label>' +
            '<label>Max actuadores a la vez<input type="number" name="maxSimultaneas" value="1"></label>' +
            '<p><button class="create" type="submit">Crear zona</button></p></form></fieldset>' +

            (s.zonas.length ? (
                '<fieldset><legend>Agregar actuador</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas">' +
                '<label>Zona<select name="zonaId">' + opcionesZonas + '</select></label>' +
                '<label>Nombre<input name="nombre" required></label>' +
                '<label>Tipo<select name="tipo" onchange="document.getElementById(\'campos-basico\').style.display = this.value===\'cortina\' ? \'none\' : \'\'; document.getElementById(\'campos-cortina\').style.display = this.value===\'cortina\' ? \'\' : \'none\';">' +
                '<option value="basico">Basico (un rele: fan, heater, bomba, valvula, cortina basica sin auto-apagado por sentido)</option>' +
                '<option value="cortina">Cortina (dos reles: uno para subir, uno para bajar)</option>' +
                '</select></label>' +
                '<div id="campos-basico"><label>Canal (coil)<input type="number" name="canal"></label></div>' +
                '<div id="campos-cortina" style="display:none;"><label>Canal subir (coil)<input type="number" name="canalSubir"></label><label>Canal bajar (coil)<input type="number" name="canalBajar"></label></div>' +
                '<label>Auto-apagado de seguridad en segundos (opcional -- para motores sin limite fisico confiable, ej. cortinas; si se deja vacio usa el limite general de la zona)<input type="number" name="autoApagadoSeg" placeholder="Ej: 45"></label>' +
                '<p><button class="create" type="submit">Agregar actuador</button></p></form></fieldset>'
            ) : '<p><em>Cre&aacute; una zona primero para poder agregarle actuadores.</em></p>') +

            '<h3>Sensores</h3>' +
            '<table><tr><th>Nombre</th><th>Tipo</th><th>Origen</th><th>Acciones</th></tr>' + sensoresRows + '</table>' +
            '<fieldset><legend>Crear sensor</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/sensores">' +
            '<label>Nombre<input name="nombre" required></label>' +
            '<label>Tipo<select name="tipo"><option value="temperatura">Temperatura</option><option value="humedad">Humedad</option><option value="par">PAR (luz)</option><option value="otro">Otro</option></select></label>' +
            '<label>Unidad<input name="unidad" placeholder="&deg;F, %, ..."></label>' +
            '<label>Fuente<select name="fuente"><option value="home_assistant">Home Assistant</option><option value="mqtt">MQTT (Dragino/ChirpStack)</option></select></label>' +
