        'table{border-collapse:collapse;width:100%;margin:16px 0}th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:14px;vertical-align:top}' +
        'th{background:#0E7C86;color:#fff}.ok{color:#1a7f37;font-weight:700}.bad{color:#b42318;font-weight:700}' +
        'button{cursor:pointer;border:none;border-radius:4px;padding:5px 10px;font-size:12px;margin:2px 0}' +
        '.del{background:#b42318;color:#fff}' +
        'fieldset{margin-top:24px;border:1px solid #ccc;border-radius:6px}label{display:block;margin:10px 0}input,select{padding:6px;margin:4px 0;width:100%;box-sizing:border-box}' +
