Promise.all([
    global.get('pgPool').query('SELECT id, name FROM riego_hub.areas ORDER BY name'),
    global.get('pgPool').query('SELECT id, username, role, must_change_password FROM riego_hub.users ORDER BY username'),
    global.get('pgPool').query('SELECT user_id, area_id FROM riego_hub.user_areas')
]).then(function(results) {
    var areas = results[0].rows;
    var users = results[1].rows;
    var assigns = results[2].rows;
    var areasByUser = {};
    assigns.forEach(function(a) {
        areasByUser[a.user_id] = areasByUser[a.user_id] || [];
        areasByUser[a.user_id].push(a.area_id);
    });

    var rows = users.map(function(u) {
        var misAreas = (areasByUser[u.id] || []);
        var areaNombres = misAreas.length ? misAreas.map(esc).join(', ') : '<span class="bad">sin areas asignadas</span>';
        var pendiente = u.must_change_password ? '<span class="bad">debe cambiar password</span>' : '<span class="ok">activa</span>';
        var checks = areas.map(function(a) {
            var checked = misAreas.indexOf(a.id) !== -1 ? ' checked' : '';
            return '<label class="chk"><input type="checkbox" name="areas" value="' + esc(a.id) + '"' + checked + '> ' + esc(a.name) + '</label>';
        }).join('');
        return '<tr><td>' + esc(u.username) + '</td><td>' + esc(u.role) + '</td><td>' + areaNombres + '</td><td>' + pendiente + '</td>' +
            '<td><form method="POST" action="/hub/usuarios/' + u.id + '/asignar">' + checks + '<br><button class="create" type="submit">Guardar areas</button></form>' +
            '<form method="POST" action="/hub/usuarios/' + u.id + '/eliminar" onsubmit="return confirm(\'Eliminar ' + esc(u.username) + '?\');" style="margin-top:8px;"><button class="del" type="submit">Eliminar usuario</button></form></td></tr>';
    }).join('');
    if (!rows) rows = '<tr><td colspan="5">Todavia no hay usuarios.</td></tr>';

    var areaChecksNuevo = areas.map(function(a) {
        return '<label class="chk"><input type="checkbox" name="areas" value="' + esc(a.id) + '"> ' + esc(a.name) + '</label>';
    }).join('');

    var body = '<table><tr><th>Usuario</th><th>Rol</th><th>Areas asignadas</th><th>Estado</th><th>Acciones</th></tr>' + rows + '</table>' +
        '<fieldset><legend>Crear usuario nuevo (o resetear password de uno existente)</legend>' +
        '<form method="POST" action="/hub/usuarios">' +
        '<label>Usuario<input name="username" required></label>' +
        '<label>Password temporal (minimo 8 caracteres)<input name="password" type="password" required minlength="8"></label>' +
        '<label>Rol<select name="role"><option value="estandar">Estandar</option><option value="admin">Administrador</option></select></label>' +
        '<label>Areas donde puede operar</label>' + areaChecksNuevo +
        '<p><button class="create" type="submit">Crear / actualizar usuario</button></p>' +
        '</form></fieldset>';
    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = page('Usuarios', body);
    node.send(msg);
}).catch(function(err) {
    msg.statusCode = 500;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = page('Error', '<p>Error: ' + esc(err.message) + '</p>');
    node.send(msg);
});
