            global.get('pgPool').query(
                'INSERT INTO riego_hub.user_areas (user_id, area_id) VALUES ' + values + ' ON CONFLICT DO NOTHING',
                [userId].concat(areas)
            ).then(function() {
                msg.statusCode = 302; msg.headers = { Location: '/hub/usuarios' }; node.send(msg);
