}
var body = msg.payload || {};
var userId = Number(body.user_id);
var currentPassword = body.currentPassword;
var newPassword = body.newPassword;
if (!Number.isSafeInteger(userId) || userId < 1 || typeof currentPassword !== 'string' || typeof newPassword !== 'string' || newPassword.length < 8 || newPassword === currentPassword) {
    msg.statusCode = 400; msg.payload = { ok: false, error: 'Usa una contrasena nueva diferente de al menos 8 caracteres' }; return msg;
}
var pool = global.get('pgPool');
pool.query('SELECT password_hash FROM riego_hub.users WHERE id=$1', [userId]).then(async function(result) {
    var user = result.rows[0];
    if (!user || !bcrypt.compareSync(currentPassword, user.password_hash)) {
        msg.statusCode = 400; msg.payload = { ok: false, error: 'Contrasena actual incorrecta' }; return node.send(msg);
    }
    var hash = bcrypt.hashSync(newPassword, 10);
    var updated = await pool.query('UPDATE riego_hub.users SET password_hash=$1, must_change_password=false, updated_at=now() WHERE id=$2 AND password_hash=$3', [hash, userId, user.password_hash]);
    msg.statusCode = updated.rowCount === 1 ? 200 : 409;
    msg.payload = updated.rowCount === 1 ? { ok: true } : { ok: false, error: 'La contrasena cambio. Vuelve a ingresar.' };
    node.send(msg);
}).catch(function() {
    msg.statusCode = 500; msg.payload = { ok: false, error: 'Error interno' }; node.send(msg);
});
